// Generated by sel-pull (Shared Element Library): do not edit, it is replaced by the next "sel-pull firebase".
//
// npm run users:import: adds the company's users and groups (pulled with "sel-pull users" into .sel/directory.json) to this app's Firestore:
// the group list, everyone on the app's domain who is not there yet (with their name), and their group memberships.
//
//   npm run users:import                 a DRY RUN against the live project: reads, prints what would change, writes nothing
//   npm run users:import -- --apply      does it (asks you to type the project id first; --yes skips the question)
//   npm run users:import -- --admins     the directory's admins also become admins here (without this nobody is promoted)
//   npm run users:import -- --emulator   the local emulators instead of the live project (npm run dev must be running)
//
// It only ever ADDS: nobody is removed, no group is taken from anyone, nobody is demoted, existing names are kept. That also holds while
// the app is in use: lists (a person's groups, the admins, the group names) are written as Firestore array unions of just the additions,
// and a name only when the person still has none, both inside a transaction, so what another writer added between the dry run and the
// write is never overwritten. Running it again is safe (it finds nothing left to add). Staff data stays on this machine: the list never goes
// into public/ (Hosting would serve it to anyone).
//
// Against the live project it needs your own Google login once (no key file): gcloud auth application-default login
import fs from "node:fs";
import path from "node:path";
import readline from "node:readline/promises";
import { fileURLToPath, pathToFileURL } from "node:url";

/**
 * What importing `directory` would do to `state` ({ users: Map email -> { groups, name }, profiles: Set of emails, admins: [emails],
 * groups: [names] }, what Firestore has now). Pure: returns { summary, writes } and touches nothing. A write is
 * { path, union: { field: [values to ADD to that list] }, ifAbsent: { field: value to set only while the field is still empty } }:
 * it names the additions only, never a whole list, so applying it cannot take away what somebody else added meanwhile.
 */
export function planImport(directory, state, { domain, admins = false }) {
  const suffix = `@${String(domain).toLowerCase()}`;
  const people = directory.users.filter((u) => String(u.email).toLowerCase().endsWith(suffix));
  const known = new Set([...state.users.keys(), ...state.profiles, ...state.admins]);
  const writes = [];
  const summary = { people: 0, groups: 0, memberships: 0, admins: 0, skipped: directory.users.length - people.length };

  const haveGroups = new Set(state.groups);
  const newGroups = [...new Set(directory.groups)].filter((g) => !haveGroups.has(g)).sort((a, b) => a.localeCompare(b));
  summary.groups = newGroups.length;
  if (newGroups.length) writes.push({ path: "settings/groups", union: { names: newGroups }, ifAbsent: {} });

  for (const u of people) {
    const email = u.email.toLowerCase();
    const have = (state.users.get(email) || {}).groups;
    const haveList = Array.isArray(have) ? have : [];
    const added = [...new Set(u.groups)].filter((g) => !haveList.includes(g)).sort();
    const isNew = !known.has(email);
    if (isNew) summary.people++;
    summary.memberships += added.length;
    if (!isNew && !added.length) continue;
    writes.push({
      path: `users/${email}`,
      union: added.length ? { groups: added } : {},
      ifAbsent: { ...(isNew && u.name ? { name: u.name } : {}), ...(isNew && !added.length ? { groups: [] } : {}) }, // a new person's record always has a groups list
    });
  }

  if (admins) {
    const current = new Set(state.admins.map((e) => e.toLowerCase()));
    const promoted = [...new Set(people.filter((u) => u.admin && !current.has(u.email.toLowerCase())).map((u) => u.email.toLowerCase()))].sort();
    summary.admins = promoted.length;
    if (promoted.length) writes.push({ path: "settings/admins", union: { emails: promoted }, ifAbsent: {} });
  }
  return { summary, writes };
}

/**
 * Applies a plan to Firestore, one transaction per document (10 at a time): array fields get FieldValue.arrayUnion of the additions, other
 * fields are set only while absent. A list field that holds something else than a list is left alone and reported. Returns
 * { failed: [{ path, message }], warnings }; it never throws for one document, so the rest still gets done and a second run finishes.
 */
export async function applyPlan(db, FieldValue, writes) {
  const failed = [];
  const warnings = [];
  const apply = (w) => db.runTransaction(async (t) => {
    const ref = db.doc(w.path);
    const snap = await t.get(ref);
    const have = snap.exists ? snap.data() || {} : {};
    const data = {};
    for (const [field, values] of Object.entries(w.union)) {
      if (have[field] !== undefined && have[field] !== null && !Array.isArray(have[field])) { warnings.push(`${w.path}: ${field} is not a list, left alone`); continue; }
      data[field] = FieldValue.arrayUnion(...values);
    }
    for (const [field, value] of Object.entries(w.ifAbsent)) if ((have[field] === undefined || have[field] === null) && !(field in data)) data[field] = value;
    if (Object.keys(data).length) t.set(ref, data, { merge: true });
  });
  for (let i = 0; i < writes.length; i += 10) {
    const results = await Promise.allSettled(writes.slice(i, i + 10).map(apply));
    results.forEach((r, j) => { if (r.status === "rejected") failed.push({ path: writes[i + j].path, message: (r.reason && r.reason.message) || String(r.reason) }); });
  }
  return { failed, warnings };
}

const describe = (s) => [s.people && `${s.people} new people`, s.groups && `${s.groups} new groups`, s.memberships && `${s.memberships} group memberships`, s.admins && `${s.admins} new admins`].filter(Boolean).join(", ");

async function main() {
  const args = new Set(process.argv.slice(2));
  const known = new Set(['--apply', '--yes', '--admins', '--emulator']);
  for (const arg of args) if (!known.has(arg)) throw new Error(`Unknown option ${JSON.stringify(arg)}. Nothing was written. Supported: ${[...known].join(', ')}`);
  const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "../..");
  const read = (rel) => fs.readFileSync(path.join(ROOT, rel), "utf8");
  const fail = (message) => { console.error(message); process.exit(1); };

  const file = path.join(ROOT, ".sel", "directory.json");
  if (!fs.existsSync(file)) fail("No users and groups here yet. Run first:  node scripts/sel-pull.mjs users");
  const directory = JSON.parse(fs.readFileSync(file, "utf8"));
  const domain = (read("public/js/config.js").match(/ALLOWED_DOMAIN = "([^"]+)"/) || [])[1];
  if (!domain) fail("Could not read ALLOWED_DOMAIN from public/js/config.js.");
  const projectId = JSON.parse(read(".firebaserc")).projects.default;
  const emulator = args.has("--emulator");

  if (emulator) {
    const firebase = JSON.parse(read("firebase.json"));
    const settings = (firebase.emulators || {}).firestore || {};
    process.env.FIRESTORE_EMULATOR_HOST = `${settings.host || "127.0.0.1"}:${settings.port || 8080}`;
  } else if (process.env.FIRESTORE_EMULATOR_HOST) {
    fail("FIRESTORE_EMULATOR_HOST is set, so this would write to the emulator. Unset it, or pass --emulator.");
  } else process.env.METADATA_SERVER_DETECTION = "none"; // not on a Google Cloud machine: your own login is the credential

  const { initializeApp, applicationDefault } = await import("firebase-admin/app");
  const { getFirestore, FieldValue } = await import("firebase-admin/firestore");
  let credential;
  if (!emulator) {
    credential = applicationDefault();
    try { await credential.getAccessToken(); } catch {
      fail("No Google login for scripts on this machine yet. Run this once, then try again:\n  gcloud auth application-default login");
    }
  }
  const db = getFirestore(initializeApp({ projectId, ...(credential ? { credential } : {}) }, "users-import"));

  console.log(`${emulator ? "The local emulators" : `The LIVE project ${projectId}`}, domain @${domain}: reading...`);
  const [usersSnap, profilesSnap, adminsDoc, groupsDoc] = await Promise.all([
    db.collection("users").get(), db.collection("userProfiles").get(), db.doc("settings/admins").get(), db.doc("settings/groups").get(),
  ]);
  const state = {
    users: new Map(usersSnap.docs.map((d) => [d.id.toLowerCase(), d.data()])),
    profiles: new Set(profilesSnap.docs.map((d) => d.id.toLowerCase())),
    admins: (adminsDoc.exists && adminsDoc.data().emails) || [],
    groups: (groupsDoc.exists && groupsDoc.data().names) || [],
  };
  const { summary, writes } = planImport(directory, state, { domain, admins: args.has("--admins") });
  if (summary.skipped) console.log(`${summary.skipped} directory users are not @${domain}: left out.`);
  if (!writes.length) { console.log("Nothing to add: everyone and every group in the directory is here already."); return; }
  console.log(`Would add ${describe(summary)} (${writes.length} documents). Nobody is removed or demoted.`);
  if (!args.has("--apply")) { console.log("This was a dry run. Add --apply to do it."); return; }

  if (!emulator && !args.has("--yes")) {
    if (!process.stdin.isTTY) fail("Not a terminal, so no question can be asked: pass --yes to write to the live project.");
    const rl = readline.createInterface({ input: process.stdin, output: process.stdout });
    const answer = await rl.question(`Type the project id (${projectId}) to write these to the LIVE database: `);
    rl.close();
    if (answer.trim() !== projectId) fail("Not the project id: nothing was written.");
  }
  const { failed, warnings } = await applyPlan(db, FieldValue, writes);
  for (const w of warnings) console.warn(`Warning, ${w}`);
  if (failed.length) {
    for (const f of failed.slice(0, 20)) console.error(`  not written: ${f.path} (${f.message})`);
    throw new Error(`${failed.length} of ${writes.length} documents were not written (the rest was). It only adds, so run it again: it finishes what is missing.`);
  }
  console.log(`Done: ${describe(summary)}.`);
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  main().catch((err) => { console.error(`Failed: ${err.message}`); process.exit(1); });
}
